// ===== 手写 MyPromise（教学简化版，理解机制用） =====
const PENDING = 'pending';
const FULFILLED = 'fulfilled';
const REJECTED = 'rejected';

class MyPromise {
  constructor(executor) {
    this.status = PENDING;
    this.value = undefined;
    this.callbacks = []; // 存储 pending 阶段注册的回调

    const resolve = (value) => {
      if (this.status !== PENDING) return; // 状态只能变一次
      // 如果 resolve 的是 thenable，需要等待它 settle
      if (value && typeof value.then === 'function') {
        value.then(resolve, reject);
        return;
      }
      this.status = FULFILLED;
      this.value = value;
      this.callbacks.forEach(cb => cb.onFulfilled(value));
    };

    const reject = (reason) => {
      if (this.status !== PENDING) return;
      this.status = REJECTED;
      this.value = reason;
      this.callbacks.forEach(cb => cb.onRejected(reason));
    };

    try {
      executor(resolve, reject); // executor 同步抛异常 → reject
    } catch (e) {
      reject(e);
    }
  }

  then(onFulfilled, onRejected) {
    // 值穿透：不是函数就包装成恒等/抛出
    onFulfilled = typeof onFulfilled === 'function' ? onFulfilled : v => v;
    onRejected = typeof onRejected === 'function' ? onRejected : r => { throw r; };

    const promise2 = new MyPromise((resolve, reject) => {
      const handle = (callback) => {
        // 用 setTimeout 模拟微任务（真实引擎用 queueMicrotask）
        setTimeout(() => {
          try {
            const result = callback(this.value);
            resolvePromise(promise2, result, resolve, reject);
          } catch (e) {
            reject(e);
          }
        });
      };

      if (this.status === FULFILLED) {
        handle(onFulfilled);
      } else if (this.status === REJECTED) {
        handle(onRejected);
      } else {
        this.callbacks.push({
          onFulfilled: () => handle(onFulfilled),
          onRejected: () => handle(onRejected)
        });
      }
    });
    return promise2; // then 返回新 Promise
  }

  catch(onRejected) { return this.then(null, onRejected); }
  finally(cb) {
    return this.then(
      v => MyPromise.resolve(cb()).then(() => v),
      r => MyPromise.resolve(cb()).then(() => { throw r; })
    );
  }
}

// 处理 resolve 的返回值是否是 Promise/thenable
function resolvePromise(promise2, x, resolve, reject) {
  if (promise2 === x) { reject(new TypeError('循环引用')); return; }
  if (x instanceof MyPromise) {
    x.then(resolve, reject);
  } else {
    resolve(x); // 普通值直接 resolve
  }
}

// ===== Promise.all 手写 =====
function promiseAll(promises) {
  return new Promise((resolve, reject) => {
    const results = [];
    let fulfilledCount = 0;
    const items = Array.from(promises);
    if (items.length === 0) { resolve(results); return; }

    items.forEach((p, i) => {
      Promise.resolve(p).then(
        val => {
          results[i] = val; // 用索引保证顺序
          if (++fulfilledCount === items.length) resolve(results);
        },
        reason => reject(reason) // 任一失败立即失败
      );
    });
  });
}

// ===== 并发池控制示例 =====
async function asyncPool(limit, items, fn) {
  const results = [];
  const executing = new Set();
  for (const [i, item] of items.entries()) {
    const p = Promise.resolve(fn(item, i)).then(r => { executing.delete(p); return r; });
    results.push(p);
    executing.add(p);
    if (executing.size >= limit) await Promise.race(executing);
  }
  return Promise.all(results);
}
